<script>
export const page={name:"sales-exports",path:"/sales/exports",title:"我的匯出工作",requires:{permissions:["sales.view"]},menu:{group:"salesOrderManagement",icon:"download",order:40}};
</script>
<script setup>
import {onBeforeUnmount,ref,watch} from "vue";
import PageHeader from "@/framework/layout/PageHeader.vue";
import {useSessionStore} from "@/stores/session.js";
import sales from "@/services/sales.js";
const session=useSessionStore(),jobs=ref([]),pageNumber=ref(1),total=ref(0),loading=ref(false),error=ref(""),downloading=ref(null),downloadError=ref("");
const labels={QUEUED:"等待處理",PROCESSING:"處理中",COMPLETED:"可下載",FAILED:"失敗",EXPIRED:"已到期"};let timer,controller,downloadController,generation=0,disposed=false;
function stop(){generation++;clearTimeout(timer);controller?.abort();loading.value=false;}
async function refresh(){stop();if(disposed||document.hidden||!session.user?.id)return;controller=new AbortController();const signal=controller.signal,current=generation;loading.value=true;error.value="";
 try{const result=await sales.listExports({page:pageNumber.value,pageSize:20,signal});if(current!==generation)return;jobs.value=result.items;total.value=result.total;if(jobs.value.some(job=>["QUEUED","PROCESSING"].includes(job.status)))timer=setTimeout(refresh,2000);}
 catch(cause){if(signal.aborted||current!==generation)return;jobs.value=[];total.value=0;error.value="無法讀取匯出工作；請重試或確認查閱權限。";if(![401,403].includes(cause.status))timer=setTimeout(refresh,5000);}
 finally{if(current===generation)loading.value=false;}}
function visibility(){if(document.hidden){stop();downloadController?.abort();downloading.value=null;}else refresh();}
watch(()=>session.user?.id,()=>{stop();downloadController?.abort();jobs.value=[];total.value=0;pageNumber.value=1;downloadError.value="";downloading.value=null;refresh();},{immediate:true});
watch(pageNumber,refresh);document.addEventListener("visibilitychange",visibility);onBeforeUnmount(()=>{disposed=true;stop();downloadController?.abort();document.removeEventListener("visibilitychange",visibility);});
async function download(job){if(downloading.value!==null)return;downloadController=new AbortController();const signal=downloadController.signal;downloading.value=job.id;downloadError.value="";try{const {blob,fileName}=await sales.downloadExport(job.id,{signal});if(signal.aborted)return;const url=URL.createObjectURL(blob);try{const link=document.createElement("a");link.href=url;link.download=fileName??`Sales-export-${job.id}.csv`;link.click();}finally{URL.revokeObjectURL(url);}}catch(cause){if(signal.aborted)return;downloadError.value=cause.status===410?"檔案已到期或不存在；請從原篩選重新建立匯出。":"下載失敗；請重試或確認查閱權限。";await refresh();}finally{if(!signal.aborted)downloading.value=null;}}
</script>
<template><div><PageHeader title="我的匯出工作" subtitle="只顯示本人建立的匯出；完成後檔案保留 7 天。"><template #actions><q-btn flat label="Active 訂單" to="/sales/orders" /><q-btn flat label="封存篩選" to="/sales/archive" /><q-btn flat label="重新讀取匯出" @click="refresh" /></template></PageHeader><div class="q-pa-md" :aria-busy="loading"><p v-if="loading" role="status">正在讀取匯出工作…</p><q-banner v-if="error" role="alert" class="bg-negative text-white">{{ error }}</q-banner><q-banner v-if="downloadError" role="alert" class="bg-negative text-white">{{ downloadError }}</q-banner><p v-if="!loading&&!error&&!jobs.length" role="status">目前沒有匯出工作；請從 Active 或封存篩選建立。</p><q-card v-for="job in jobs" :key="job.id" class="q-mb-md" flat bordered><q-card-section><h2 class="text-h6 q-mt-none">匯出 #{{ job.id }} — {{ job.scope }}</h2><p :role="['QUEUED','PROCESSING'].includes(job.status)?'status':undefined">{{ labels[job.status] }} · {{ job.rowCount }} 筆</p><p>建立：{{ new Date(job.createdAt).toLocaleString('zh-HK',{timeZone:'Asia/Hong_Kong'}) }}<template v-if="job.expiresAt"> · 到期：{{ new Date(job.expiresAt).toLocaleString('zh-HK',{timeZone:'Asia/Hong_Kong'}) }}</template></p><pre class="sales-export-snapshot">{{ JSON.stringify(job.filters,null,2) }}</pre><p v-if="job.status==='FAILED'">{{ job.errorCode==='SALES_EXPORT_ROW_LIMIT_EXCEEDED'?'超過 250,000 筆上限，請縮小篩選。':'匯出失敗，請核對權限與篩選後重新建立。' }}</p><p v-if="job.status==='EXPIRED'">檔案已到期；工作記錄仍保留。</p><q-btn v-if="job.status==='COMPLETED'" :label="`下載 CSV #${job.id}`" color="primary" :loading="downloading===job.id" :disable="downloading!==null" @click="download(job)" /></q-card-section></q-card><q-pagination v-if="total>20" v-model="pageNumber" :max="Math.ceil(total/20)" aria-label="匯出工作頁碼" /></div></div></template>
<style scoped>.sales-export-snapshot{white-space:pre-wrap;overflow-wrap:anywhere}</style>
